import Foundation
import GRDB
import QuranKit
import SQLitePersistence

/// Read-only lookup in the index generated by Tools/build-similar-verses.py.
public struct GRDBSimilarVersePersistence: Sendable {
    public init(fileURL: URL) {
        database = DatabaseConnection(url: fileURL, deletesBadFile: false)
    }

    public func matches(for verse: AyahNumber) async throws -> [AyahNumber] {
        try await database.read { connection in
            let rows = try Row.fetchAll(
                connection,
                sql: """
                WITH matches AS (
                    SELECT match_sura AS sura, match_ayah AS ayah, sources, shared_ngram, source_score
                    FROM verse_pairs WHERE sura = :sura AND ayah = :ayah
                    UNION ALL
                    SELECT sura, ayah, sources, shared_ngram, source_score
                    FROM verse_pairs WHERE match_sura = :sura AND match_ayah = :ayah
                )
                SELECT sura, ayah FROM matches
                WHERE sources > 0 AND shared_ngram >= 2
                ORDER BY shared_ngram DESC, source_score DESC, sura, ayah
                """,
                arguments: ["sura": verse.sura.suraNumber, "ayah": verse.ayah]
            )
            return rows.compactMap { AyahNumber(quran: verse.quran, sura: $0["sura"], ayah: $0["ayah"]) }
        }
    }

    private let database: DatabaseConnection
}
